"""IVW-Exportlogik auf Basis der SQLMesh-Tagesaggregation.

Die eSuite-Importe werden direkt in
``dbm_lesermarkt.tb_ivw_fulfillment_detail`` gespeichert. Das SQLMesh-Modell
``dbm_mart.ivw_fulfillment_daily`` bildet daraus die fachlich relevante
Tagesaggregation. Dieses Modul liest ausschliesslich dieses Tagesmodell und
formt daraus die zwei Exportsichten:

- ``tagesdaten``: Tagesdaten inklusive der fuer den Export benoetigten Attribute.
- ``zeitraum``: Der bisherige, ueber einen Zeitraum aggregierte IVW-Report.

Die alte Python-Aufbereitung aus ``tb_ivw_grundlage`` und die separate
Firmenabo-Ergaenzung werden bewusst nicht mehr verwendet.
"""

import logging
import re
from typing import Any

import numpy as np
import pandas as pd

logger = logging.getLogger(__name__)

_FILTER_VALUE_PATTERN = re.compile(r"^[A-Za-z0-9_-]+$")


def _prepare_filters(art_filter: str, welt_filter: str) -> tuple[str, str]:
    """Bereitet kommagetrennte Art- und Weltfilter fuer die SQL-Abfrage vor.

    Die Werte werden auf einfache Bezeichner begrenzt, damit sie sicher in
    die ``IN``-Klauseln eingesetzt werden koennen.
    """
    return _format_filter_values(art_filter), _format_filter_values(welt_filter)


def _format_filter_values(filter_value: str) -> str:
    """Formatiert einen kommagetrennten Filter als SQL-IN-Werteliste."""
    values = [value.strip() for value in filter_value.split(",") if value.strip()]
    if not values:
        raise ValueError("Mindestens ein Filterwert ist erforderlich.")

    invalid_values = [value for value in values if not _FILTER_VALUE_PATTERN.fullmatch(value)]
    if invalid_values:
        raise ValueError(f"Ungueltige Filterwerte: {', '.join(invalid_values)}")

    return ",".join(f"'{value}'" for value in values)


def load_ivw_daily_from_sqlmesh(
    cursor: Any,
    art_in: str,
    welt_in: str,
    start_date: str,
    end_date: str,
) -> pd.DataFrame:
    """Laedt die IVW-Tagesdaten aus dem SQLMesh-Modell.

    Das Detailimportmodul setzt ``is_ivw_relevant`` bereits beim Import.
    Das SQLMesh-Modell summiert ausschliesslich diese relevanten Detailzeilen
    pro Lieferungstag. Hier werden nur die Attribute fuer das bisherige
    Exportschema nachgeschlagen; es erfolgt keine weitere Fulfilment-Filterung.
    """
    cursor.execute(
        f"""
        SELECT
            daily.art AS art,
            daily.pva AS PVA,
            daily.gesamt_pva AS Gesamt_PVA,
            pva_mapping.Bezeichnung AS Bezeichnung,
            daily.welt AS vkorg,
            daily.objekt AS Objekt,
            daily.ivwcategory AS IVWCategory,
            daily.meldung AS Meldung,
            DATE(daily.lieferdatum) AS LIEFERDATUM,
            DATE(daily.ausgabedatum) AS AUSGABEDATUM,
            COALESCE(category.Verkauf, 0) AS Verkauf,
            COALESCE(category.Verbreitung, 0) AS Verbreitung,
            COALESCE(category.Druckauflage, 0) AS Druckauflage,
            CAST(daily.fulfilment_count AS DECIMAL(18, 4)) AS Gesamtmenge
        FROM dbm_mart.ivw_fulfillment_daily AS daily
        LEFT JOIN tb_mapping_pva AS pva_mapping
            ON pva_mapping.SAP = daily.pva
        LEFT JOIN (
            SELECT
                IVWCategory,
                MAX(Verkauf) AS Verkauf,
                MAX(Verbreitung) AS Verbreitung,
                MAX(Druckauflage) AS Druckauflage
            FROM tb_ivw_mapping_ivwcategory
            GROUP BY IVWCategory
        ) AS category
            ON category.IVWCategory = daily.ivwcategory
        WHERE daily.art IN ({art_in})
            AND daily.welt IN ({welt_in})
            AND daily.lieferdatum >= %s
            AND daily.lieferdatum <= %s
        """,
        (start_date, end_date),
    )

    daily = pd.DataFrame(cursor.fetchall())
    for date_column in ("LIEFERDATUM", "AUSGABEDATUM"):
        if date_column in daily:
            daily[date_column] = pd.to_datetime(daily[date_column])

    return daily


def _load_et_calendar_counts(cursor: Any, start_date: str, end_date: str) -> dict[str, int]:
    """Zaehlt die Erscheinungstage fuer die drei IVW-Rhythmen im Zeitraum.

    Die Zeitraumgrenze richtet sich nach ``cal_date``. In unvollstaendigen
    Zeitraeumen werden nur Erscheinungstage bis zum letzten im SQLMesh-
    Tagesmodell vorhandenen Lieferdatum gezaehlt. Damit verwenden Zaehler
    und Nenner denselben Datenstand.
    """
    cursor.execute(
        """
        SELECT MAX(lieferdatum) AS max_lieferdatum
        FROM dbm_mart.ivw_fulfillment_daily
        WHERE lieferdatum >= %s
            AND lieferdatum <= %s
        """,
        (start_date, end_date),
    )
    data_end = cursor.fetchone() or {}
    max_lieferdatum = data_end.get("max_lieferdatum")

    if max_lieferdatum is None:
        return {"Mo-Sa": 0, "Mo-Fr": 0, "Sa": 0}

    cursor.execute(
        """
        SELECT
            SUM(CASE WHEN DAYOFWEEK(issue_date) BETWEEN 2 AND 7 THEN 1 ELSE 0 END) AS mo_sa,
            SUM(CASE WHEN DAYOFWEEK(issue_date) BETWEEN 2 AND 6 THEN 1 ELSE 0 END) AS mo_fr,
            SUM(CASE WHEN DAYOFWEEK(issue_date) = 7 THEN 1 ELSE 0 END) AS sa
        FROM tb_et_calendar
        WHERE et_date = 1
            AND cal_date BETWEEN %s AND %s
            AND cal_date <= %s
        """,
        (start_date, end_date, max_lieferdatum),
    )
    row = cursor.fetchone() or {}

    return {
        "Mo-Sa": int(row.get("mo_sa") or 0),
        "Mo-Fr": int(row.get("mo_fr") or 0),
        "Sa": int(row.get("sa") or 0),
    }


def _create_daterange_aggregation(
    daily_agg: pd.DataFrame,
    start_date: str,
    end_date: str,
    et_counts: dict[str, int],
) -> pd.DataFrame:
    """Erzeugt den formatkompatiblen, aggregierten IVW-Gesamtexport.

    Die Berechnung entspricht dem bisherigen Report: fuer Mo-Sa, Mo-Fr und
    Samstag werden Gesamtmenge, Anzahl Erscheinungstage und der kaufmaennisch
    gerundete Durchschnittsschnitt (DS) ausgegeben.
    """
    logger.info("Erstelle Datumsbereich-Aggregation aus SQLMesh-Tagesdaten.")

    if daily_agg.empty:
        return pd.DataFrame(columns=_KOMPLETT_COLUMNS)

    daily_agg = daily_agg.copy()
    daily_agg["AUSGABEDATUM"] = pd.to_datetime(daily_agg["AUSGABEDATUM"])
    daily_agg["weekday_mysql"] = ((daily_agg["AUSGABEDATUM"].dt.dayofweek + 1) % 7) + 1

    group_columns = [
        "art",
        "PVA",
        "Gesamt_PVA",
        "Bezeichnung",
        "vkorg",
        "Objekt",
        "IVWCategory",
        "Meldung",
        "Verkauf",
        "Verbreitung",
        "Druckauflage",
    ]

    def aggregate_erscheinung(data: pd.DataFrame, label: str) -> pd.DataFrame:
        """Aggregiert die Tagesmengen fuer einen Erscheinungsrhythmus."""
        aggregated = data.groupby(group_columns, observed=True).agg(Gesamtmenge=("Gesamtmenge", "sum")).reset_index()
        aggregated["Erscheinung"] = label
        aggregated["ANZAHL_ET"] = et_counts[label]

        gesamtmenge = pd.to_numeric(aggregated["Gesamtmenge"], errors="coerce").fillna(0).to_numpy(dtype=float)
        anzahl_et = pd.to_numeric(aggregated["ANZAHL_ET"], errors="coerce").fillna(0).to_numpy(dtype=float)
        durchschnitt = np.zeros(len(aggregated), dtype=float)
        np.divide(
            gesamtmenge,
            anzahl_et,
            out=durchschnitt,
            where=anzahl_et > 0,
        )
        aggregated["DS"] = np.floor(durchschnitt + 0.5).astype("int64")
        return aggregated

    aggregates = [
        aggregate_erscheinung(daily_agg[daily_agg["weekday_mysql"].between(2, 7)], "Mo-Sa"),
        aggregate_erscheinung(daily_agg[daily_agg["weekday_mysql"].between(2, 6)], "Mo-Fr"),
        aggregate_erscheinung(daily_agg[daily_agg["weekday_mysql"] == 7], "Sa"),
    ]
    daterange_agg = pd.concat(aggregates, ignore_index=True).rename(
        columns={
            "art": "Art",
            "vkorg": "Welt",
            "IVWCategory": "IVWKategorie",
            "Meldung": "Meldekategorie",
        }
    )

    daterange_agg["Quelle"] = "eSuite"
    daterange_agg["Zeitraum_von"] = pd.to_datetime(start_date).strftime("%d.%m.%Y")
    daterange_agg["Zeitraum_bis"] = pd.to_datetime(end_date).strftime("%d.%m.%Y")

    numeric_columns = ["Verkauf", "Verbreitung", "Druckauflage", "ANZAHL_ET", "DS"]
    daterange_agg[numeric_columns] = daterange_agg[numeric_columns].fillna(0)
    return daterange_agg[_KOMPLETT_COLUMNS]


_KOMPLETT_COLUMNS = [
    "Art",
    "PVA",
    "Gesamt_PVA",
    "Bezeichnung",
    "Welt",
    "Objekt",
    "IVWKategorie",
    "Meldekategorie",
    "Verkauf",
    "Verbreitung",
    "Druckauflage",
    "Erscheinung",
    "ANZAHL_ET",
    "Gesamtmenge",
    "DS",
    "Quelle",
    "Zeitraum_von",
    "Zeitraum_bis",
]
